import { useId, useLayoutEffect, useRef } from "react";

const FOCUSABLE_SELECTOR =
  "a[href], button, input, select, textarea, [tabindex]";

const bodyScrollLocks = new WeakMap();

function getFocusableElements(container) {
  return Array.from(container.querySelectorAll(FOCUSABLE_SELECTOR)).filter(
    (element) => {
      const tabIndex = element.getAttribute("tabindex");

      if (tabIndex !== null && Number(tabIndex) === -1) {
        return false;
      }

      const tagName = element.tagName.toLowerCase();
      const isFormControl =
        tagName === "button" ||
        tagName === "input" ||
        tagName === "select" ||
        tagName === "textarea";

      if (isFormControl && element.matches(":disabled")) {
        return false;
      }

      if (tagName === "input" && element.type === "hidden") {
        return false;
      }

      return true;
    },
  );
}

function lockBodyScroll(body) {
  let state = bodyScrollLocks.get(body);

  if (state) {
    state.count += 1;
  } else {
    state = {
      count: 1,
      previousOverflow: body.style.overflow,
    };
    bodyScrollLocks.set(body, state);
  }

  body.style.overflow = "hidden";

  let released = false;

  return () => {
    if (released) return;
    released = true;

    const currentState = bodyScrollLocks.get(body);
    if (!currentState) return;

    currentState.count -= 1;

    if (currentState.count === 0) {
      body.style.overflow = currentState.previousOverflow;
      bodyScrollLocks.delete(body);
    } else {
      body.style.overflow = "hidden";
    }
  };
}

